#!/usr/bin/env python
"""Circular packaging replenishment solver (PySCIPOpt).

Reads public data under /app/data, builds the model described in
/app/submissions/model.md, solves with SCIP (relative gap 0.0005),
validates, and writes /app/submissions/solution.csv.
"""
import csv
import json
import os
import sys

from pyscipopt import Model, quicksum

DATA = "/app/data"
SUB = "/app/submissions"
SOL_PATH = os.path.join(SUB, "solution.csv")
TOL = 1e-5


def read_data():
    with open(os.path.join(DATA, "config.json")) as f:
        cfg = json.load(f)

    days = []
    with open(os.path.join(DATA, "days.csv")) as f:
        for row in csv.DictReader(f):
            days.append((row["day"], int(row["day_index"])))
    days.sort(key=lambda x: x[1])
    day_ids = [d for d, _ in days]
    n_days = len(day_ids)

    stores = []
    with open(os.path.join(DATA, "stores.csv")) as f:
        for row in csv.DictReader(f):
            stores.append({
                "id": row["store_id"],
                "init": float(row["initial_clean_inventory"]),
                "cap": float(row["storage_capacity"]),
                "ret": float(row["return_rate"]),
                "minsvc": float(row["minimum_service_rate"]),
            })
    stores.sort(key=lambda x: x["id"])
    store_ids = [s["id"] for s in stores]

    hubs = []
    with open(os.path.join(DATA, "wash_hubs.csv")) as f:
        for row in csv.DictReader(f):
            hubs.append({
                "id": row["hub_id"],
                "clean0": float(row["initial_clean"]),
                "dirty0": float(row["initial_dirty"]),
                "washcap": float(row["daily_wash_capacity"]),
            })
    hubs.sort(key=lambda x: x["id"])
    hub_ids = [h["id"] for h in hubs]

    demand = {}
    with open(os.path.join(DATA, "demand.csv")) as f:
        for row in csv.DictReader(f):
            demand[(row["store_id"], row["day"])] = float(row["forecast_orders"])

    lanes = {}
    with open(os.path.join(DATA, "store_hub_lanes.csv")) as f:
        for row in csv.DictReader(f):
            key = (row["store_id"], row["hub_id"])
            lanes[key] = {
                "capC": float(row["clean_lane_capacity"]),
                "capR": float(row["dirty_lane_capacity"]),
                "cc": float(row["clean_ship_cost"]),
                "rc": float(row["dirty_return_cost"]),
            }
    return cfg, day_ids, n_days, stores, store_ids, hubs, hub_ids, demand, lanes


def main():
    cfg, day_ids, n_days, stores, store_ids, hubs, hub_ids, demand, lanes = read_data()

    c_clean_hold = cfg["clean_inventory_holding_cost"]
    c_dirty_hold = cfg["dirty_inventory_holding_cost"]
    c_hub_hold = cfg["hub_inventory_holding_cost"]
    c_lost = cfg["lost_order_penalty"]
    c_wash = cfg["wash_cost_per_pack"]
    tol = cfg.get("feasibility_tolerance", 1e-5)

    S = {s["id"]: s for s in stores}
    H = {h["id"]: h for h in hubs}

    # lane lists per store and per hub
    store_lanes = {s: [h for h in hub_ids if (s, h) in lanes] for s in store_ids}
    hub_lanes = {h: [s for s in store_ids if (s, h) in lanes] for h in hub_ids}

    # sanity: every store-day demand present
    for s in store_ids:
        for d in day_ids:
            if (s, d) not in demand:
                raise KeyError(f"missing demand for {s},{d}")
    # sanity: every store has at least one lane
    for s in store_ids:
        if not store_lanes[s]:
            raise KeyError(f"store {s} has no feasible lanes")

    model = Model("circular_packaging_replenishment")
    model.setParam("gaprel", 0.0005)

    time_limit = 300.0
    env_limit = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
    if env_limit is not None:
        try:
            time_limit = min(time_limit, float(env_limit))
        except ValueError:
            pass
    model.setParam("limits/time", time_limit)

    # ---------------- variables ----------------
    X = {}  # clean shipment store->hub per day
    Y = {}  # dirty return store->hub per day
    V = {}  # wash per hub per day
    U = {}  # unmet per store per day
    Sv = {}  # store end-of-day clean inventory
    CH = {}  # hub end-of-day clean inventory
    DH = {}  # hub end-of-day dirty inventory

    for s in store_ids:
        for d in day_ids:
            ub_u = demand[(s, d)] * (1.0 - S[s]["minsvc"]) + 1.0
            U[(s, d)] = model.addVar(name=f"U_{s}_{d}", vtype="I", lb=0.0, ub=max(0.0, ub_u), obj=0.0)
            Sv[(s, d)] = model.addVar(name=f"S_{s}_{d}", vtype="I", lb=0.0, ub=S[s]["cap"], obj=0.0)
        for h in store_lanes[s]:
            ln = lanes[(s, h)]
            for d in day_ids:
                X[(s, h, d)] = model.addVar(name=f"X_{s}_{h}_{d}", vtype="I", lb=0.0, ub=ln["capC"], obj=0.0)
                Y[(s, h, d)] = model.addVar(name=f"Y_{s}_{h}_{d}", vtype="I", lb=0.0, ub=ln["capR"], obj=0.0)

    for h in hub_ids:
        for d in day_ids:
            V[(h, d)] = model.addVar(name=f"V_{h}_{d}", vtype="I", lb=0.0, ub=H[h]["washcap"], obj=0.0)
            CH[(h, d)] = model.addVar(name=f"CH_{h}_{d}", vtype="I", lb=0.0, ub=None, obj=0.0)
            DH[(h, d)] = model.addVar(name=f"DH_{h}_{d}", vtype="I", lb=0.0, ub=None, obj=0.0)

    # ---------------- constraints ----------------
    for s in store_ids:
        prev = S[s]["init"]
        for d in day_ids:
            D = demand[(s, d)]
            # served orders O = D - U
            served = D - U[(s, d)]
            # store clean balance: S[t] = prev + sum X - served
            inx = quicksum(X[(s, h, d)] for h in store_lanes[s])
            model.addCons(Sv[(s, d)] == prev + inx - served, name=f"storebal_{s}_{d}")
            # dirty return linkage: sum Y = r * served
            outy = quicksum(Y[(s, h, d)] for h in store_lanes[s])
            model.addCons(outy == S[s]["ret"] * served, name=f"retlink_{s}_{d}")
            prev = Sv[(s, d)]

    for h in hub_ids:
        prev_c = H[h]["clean0"]
        prev_d = H[h]["dirty0"]
        for d in day_ids:
            ret_in = quicksum(Y[(s, h, d)] for s in hub_lanes[h])
            ship_out = quicksum(X[(s, h, d)] for s in hub_lanes[h])
            # dirty balance: DH[t] = DH[t-1] + returns - wash
            model.addCons(DH[(h, d)] == prev_d + ret_in - V[(h, d)], name=f"hubdirty_{h}_{d}")
            # wash only dirty on hand (incoming + on hand)
            model.addCons(V[(h, d)] <= prev_d + ret_in, name=f"washavail_{h}_{d}")
            # clean balance: CH[t] = CH[t-1] + wash - shipments
            model.addCons(CH[(h, d)] == prev_c + V[(h, d)] - ship_out, name=f"hubclean_{h}_{d}")
            prev_c = CH[(h, d)]
            prev_d = DH[(h, d)]

    # ---------------- objective ----------------
    obj_terms = []
    for s in store_ids:
        for d in day_ids:
            obj_terms.append(c_lost * U[(s, d)])
            obj_terms.append(c_clean_hold * Sv[(s, d)])
    for s in store_ids:
        for h in store_lanes[s]:
            ln = lanes[(s, h)]
            for d in day_ids:
                obj_terms.append(ln["cc"] * X[(s, h, d)])
                obj_terms.append(ln["rc"] * Y[(s, h, d)])
    for h in hub_ids:
        for d in day_ids:
            obj_terms.append(c_wash * V[(h, d)])
            obj_terms.append(c_hub_hold * CH[(h, d)])
            obj_terms.append(c_dirty_hold * DH[(h, d)])

    model.setObjective(quicksum(obj_terms), sense="minimize")

    # ---------------- solve ----------------
    status = "error"
    objval = None
    try:
        model.optimize()
        status = model.getStatus()
        sols = model.getNSols()
        if sols > 0:
            objval = model.getObjVal()
    except Exception as e:
        print(f"Solver error: {e}")
        status = "error"

    print(f"SCIP Status: {status}")
    try:
        print(f"Solving Time (sec): {model.getSolTime(model.getBestSol()) if model.getNSols() > 0 else 'n/a'}")
    except Exception:
        pass
    print(f"Objective value: {objval}")
    print(f"Number of solutions: {model.getNSols()}")

    # ---------------- extract solution ----------------
    rows = []
    val = {}  # (row_type, s, h, d) -> value

    def gv(var):
        try:
            return model.getVal(var)
        except Exception:
            return 0.0

    if model.getNSols() > 0:
        for s in store_ids:
            for d in day_ids:
                v = gv(U[(s, d)])
                val[("unmet", s, "", d)] = v
                sv = gv(Sv[(s, d)])
                val[("store_inv", s, "", d)] = sv
            for h in store_lanes[s]:
                for d in day_ids:
                    val[("clean_shipment", s, h, d)] = gv(X[(s, h, d)])
                    val[("dirty_return", s, h, d)] = gv(Y[(s, h, d)])
        for h in hub_ids:
            for d in day_ids:
                val[("wash", "", h, d)] = gv(V[(h, d)])
                val[("hub_clean", "", h, d)] = gv(CH[(h, d)])
                val[("hub_dirty", "", h, d)] = gv(DH[(h, d)])
    else:
        # best effort: zeros
        for s in store_ids:
            for d in day_ids:
                val[("unmet", s, "", d)] = 0.0
                val[("store_inv", s, "", d)] = 0.0
                for h in store_lanes[s]:
                    val[("clean_shipment", s, h, d)] = 0.0
                    val[("dirty_return", s, h, d)] = 0.0
        for h in hub_ids:
            for d in day_ids:
                val[("wash", "", h, d)] = 0.0
                val[("hub_clean", "", h, d)] = 0.0
                val[("hub_dirty", "", h, d)] = 0.0

    # ---------------- validation ----------------
    errors = []
    for s in store_ids:
        prev = S[s]["init"]
        for d in day_ids:
            D = demand[(s, d)]
            u = val[("unmet", s, "", d)]
            sv = val[("store_inv", s, "", d)]
            inx = sum(val[("clean_shipment", s, h, d)] for h in store_lanes[s])
            outy = sum(val[("dirty_return", s, h, d)] for h in store_lanes[s])
            served = D - u
            # store balance
            if abs(sv - (prev + inx - served)) > tol:
                errors.append(f"store clean balance mismatch {s},{d}: {sv} vs {prev + inx - served}")
            # storage
            if sv > S[s]["cap"] + tol:
                errors.append(f"store storage exceeded {s},{d}: {sv} > {S[s]['cap']}")
            if sv < -tol:
                errors.append(f"store clean inventory negative for {s},{d}: {sv}")
            # service target
            if u > (1.0 - S[s]["minsvc"]) * D + tol:
                errors.append(f"service target violated {s},{d}: unmet {u}")
            # return linkage
            if abs(outy - S[s]["ret"] * served) > tol:
                errors.append(f"dirty return linkage failed for {s},{d}: {outy} vs {S[s]['ret']*served}")
            # lane capacities
            for h in store_lanes[s]:
                ln = lanes[(s, h)]
                if val[("clean_shipment", s, h, d)] > ln["capC"] + tol:
                    errors.append(f"clean lane capacity exceeded {s},{h},{d}")
                if val[("dirty_return", s, h, d)] > ln["capR"] + tol:
                    errors.append(f"dirty lane capacity exceeded {s},{h},{d}")
            prev = sv

    for h in hub_ids:
        prev_c = H[h]["clean0"]
        prev_d = H[h]["dirty0"]
        for d in day_ids:
            ret_in = sum(val[("dirty_return", s, h, d)] for s in hub_lanes[h])
            ship_out = sum(val[("clean_shipment", s, h, d)] for s in hub_lanes[h])
            v = val[("wash", "", h, d)]
            ch = val[("hub_clean", "", h, d)]
            dh = val[("hub_dirty", "", h, d)]
            if abs(dh - (prev_d + ret_in - v)) > tol:
                errors.append(f"hub dirty balance mismatch {h},{d}: {dh} vs {prev_d + ret_in - v}")
            if abs(ch - (prev_c + v - ship_out)) > tol:
                errors.append(f"hub clean balance mismatch {h},{d}: {ch} vs {prev_c + v - ship_out}")
            if v > H[h]["washcap"] + tol:
                errors.append(f"wash capacity exceeded {h},{d}: {v} > {H[h]['washcap']}")
            if v > prev_d + ret_in + tol:
                errors.append(f"wash exceeds dirty on hand {h},{d}: {v} > {prev_d + ret_in}")
            if ch < -tol:
                errors.append(f"hub clean inventory negative for {h},{d}: {ch}")
            if dh < -tol:
                errors.append(f"hub dirty inventory negative for {h},{d}: {dh}")
            prev_c = ch
            prev_d = dh

    validation_ok = len(errors) == 0
    print(f"Validation OK: {validation_ok}")
    for e in errors[:40]:
        print("  " + e)
    if len(errors) > 40:
        print(f"  ... and {len(errors)-40} more")

    # ---------------- write solution ----------------
    def fmt(v):
        r = round(float(v), 8)
        if abs(r - round(r)) < 1e-9:
            return str(int(round(r)))
        return f"{r:.8f}"

    with open(SOL_PATH, "w", newline="") as f:
        w = csv.writer(f)
        w.writerow(["row_type", "day", "store_id", "hub_id", "value"])
        for s in store_ids:
            for d in day_ids:
                v = val[("clean_shipment", s, "", d)] if False else None
        # clean_shipment rows
        for s in store_ids:
            for h in store_lanes[s]:
                for d in day_ids:
                    v = val[("clean_shipment", s, h, d)]
                    if abs(v) > 1e-9:
                        w.writerow(["clean_shipment", d, s, h, fmt(v)])
        # dirty_return rows
        for s in store_ids:
            for h in store_lanes[s]:
                for d in day_ids:
                    v = val[("dirty_return", s, h, d)]
                    if abs(v) > 1e-9:
                        w.writerow(["dirty_return", d, s, h, fmt(v)])
        # wash rows
        for h in hub_ids:
            for d in day_ids:
                v = val[("wash", "", h, d)]
                if abs(v) > 1e-9:
                    w.writerow(["wash", d, "", h, fmt(v)])
        # unmet rows
        for s in store_ids:
            for d in day_ids:
                v = val[("unmet", s, "", d)]
                if abs(v) > 1e-9:
                    w.writerow(["unmet", d, s, "", fmt(v)])
    print(f"Wrote {SOL_PATH}")

    try:
        model.free()
    except Exception:
        pass

    return 0 if validation_ok else 1


if __name__ == "__main__":
    sys.exit(main())
